    kalingga: {
    periods: [
      {
        start: 632,
        end: 660,
        label: "Masa Awal",
        chunks: [
          {
            topic: ["origins", "sources"],
            text: "Kalingga (disebut Ho-ling atau She-p'o dalam catatan Tiongkok) adalah kerajaan Hindu-Buddha di pesisir utara Jawa Tengah, diperkirakan berlokasi antara Pekalongan dan Jepara. Sumber sejarahnya sangat bergantung pada catatan dinasti Tiongkok — terutama Chiu T'ang-shu dan Hsin T'ang-shu — karena hampir tidak ada prasasti lokal yang tersisa dari kerajaan ini sendiri.",
            citation: "Coedès, The Indianized States of Southeast Asia (1968/1975), Ch. V §7, hlm. 78-79",
            url: "https://cdn.angkordatabase.asia/libs/docs/The-Indianized-States-of-Southeast-Asia-by-George-Coedes-z-lib.org.pdf"
          },
          {
            topic: ["relations", "trade"],
            text: "Pada masa pemerintahan Cheng-kuan (627-649 M), raja Ho-ling mengirim persembahan ke istana Tiongkok bersama-sama dengan raja To-ho-lo dan To-p'o-teng — menunjukkan Ho-ling sudah menjalin hubungan diplomatik-dagang dengan Tiongkok sejak paruh pertama abad ke-7 M, sezaman dengan awal kebangkitan Sriwijaya di Sumatra.",
            citation: "Chiu T'ang-shu (Kitab Lama Dinasti Tang), sebagaimana dikutip Poesponegoro & Notosusanto, SNI Jilid II (1984)",
            url: "https://ia801407.us.archive.org/22/items/sejarah-nasional-indonesia-jilid-2-zaman-kuno/Sejarah%20Nasional%20Indonesia%20Jilid%202%20Zaman%20Kuno_text.pdf"
          },
          {
            topic: ["territory", "economy"],
            text: "Catatan Tiongkok menggambarkan letak Ho-ling: berbatasan dengan P'o-li (kemungkinan Bali) di timur dan To-p'o-teng di barat, lautan di selatan, dan Chen-la di utara. Wilayahnya disebut subur dengan sumber air garam, dan raja-raja setempat membawahi puluhan negeri kecil — pola pemerintahan yang mirip dengan konfederasi kerajaan-kerajaan bawahan.",
            citation: "Hsin T'ang-shu (Kitab Baru Dinasti Tang), sebagaimana dikutip Poesponegoro & Notosusanto, SNI Jilid II (1984)",
            url: "https://ia801407.us.archive.org/22/items/sejarah-nasional-indonesia-jilid-2-zaman-kuno/Sejarah%20Nasional%20Indonesia%20Jilid%202%20Zaman%20Kuno_text.pdf"
          },
          {
            topic: ["religion", "relations"],
            text: "Pada 664 M, biksu Tiongkok Hui-ning (Hwi-ning) tiba di Ho-ling dan menetap selama sekitar tiga tahun, menerjemahkan sejumlah kitab suci Buddha Hinayana dengan bantuan biksu lokal bernama Jnanabhadra. Fakta bahwa Ho-ling memiliki biksu lokal yang cakap membantu penerjemahan kitab suci menunjukkan tradisi ke-Buddha-an sudah cukup mapan di Jawa pertengahan abad ke-7 M.",
            citation: "Coedès, The Indianized States of Southeast Asia (1968/1975), hlm. 79; I-Tsing (Yijing), catatan perjalanan (671-695 M)",
            url: "https://cdn.angkordatabase.asia/libs/docs/The-Indianized-States-of-Southeast-Asia-by-George-Coedes-z-lib.org.pdf"
          },
        ]
      },
      {
        start: 660,
        end: 695,
        label: "Masa Ratu Shima",
        chunks: [
          {
            topic: ["rulers", "culture"],
            text: "Ratu Shima memerintah Ho-ling sekitar 674-695 M dan tercatat dalam Chiu T'ang-shu sebagai penguasa perempuan yang menegakkan hukum sangat ketat terhadap pencurian — sampai-sampai tidak ada orang yang berani mengambil barang hilang yang tergeletak di jalan. Tradisi lokal yang berkembang kemudian (dan dicatat lebih lengkap dalam Babad Tanah Jawi serta Carita Parahiyangan) menambahkan kisah seorang raja asing yang sengaja meletakkan kantong emas di persimpangan jalan untuk menguji kejujuran rakyat Kalingga.",
            citation: "Chiu T'ang-shu (Kitab Lama Dinasti Tang); Coedès, The Indianized States of Southeast Asia, hlm. 79 (Coedès sendiri menandai bagian kisah-kisah tradisi lokal semacam ini sebagai aksresi legendaris yang tidak terverifikasi secara epigrafis)",
            url: "https://cdn.angkordatabase.asia/libs/docs/The-Indianized-States-of-Southeast-Asia-by-George-Coedes-z-lib.org.pdf"
          },
          {
            topic: ["decline", "succession"],
            text: "Menurut Carita Parahiyangan, sepeninggal Ratu Shima (±695 M), Kalingga terbagi menjadi dua: Kalingga Utara (disebut Bumi Mataram) di bawah Sanaha, cucu Ratu Shima, dan Kalingga Selatan (Bumi Sambara) di bawah Dewasinga. Pembagian ini menandai berakhirnya Kalingga sebagai satu kerajaan tunggal.",
            citation: "Carita Parahiyangan (naskah tradisi Sunda) — sumber tradisi lokal, bukan epigrafis; perlu dibaca berdampingan dengan sumber Tiongkok yang tidak mencatat detail pembagian ini",
            url: "https://id.wikipedia.org/wiki/Kerajaan_Kalingga"
          },
          {
            topic: ["succession", "relations"],
            text: "Kalingga Utara (Bumi Mataram) menjadi cikal-bakal Kerajaan Mataram Kuno: Sanjaya, cicit Ratu Shima, menggantikan neneknya sebagai penguasa Kalingga Utara pada 732 M dan kemudian mendirikan Wangsa Sanjaya di Mataram. Sementara itu, Kalingga Selatan (Bumi Sambara) di bawah Dewasinga kelak terhubung dengan Sanjaya lewat pernikahannya dengan Sudiwara, putri Dewasinga — titik simpul penting yang menyambungkan riwayat Kalingga langsung ke asal-usul Mataram Kuno.",
            citation: "Carita Parahiyangan (naskah tradisi Sunda) — sumber tradisi lokal; korelasikan dengan RAG Mataram untuk kontinuitas narasi",
            url: "https://id.wikipedia.org/wiki/Kerajaan_Kalingga"
          },
          {
            topic: ["relations", "territory"],
            text: "Selain garis keturunan ke Mataram, tradisi lokal juga mengaitkan keturunan Ratu Shima dengan kerajaan Sunda dan Galuh lewat ikatan perkawinan — menjadikan Kalingga simpul kekerabatan yang menghubungkan Jawa Tengah (Mataram), Jawa Barat (Sunda-Galuh), sekaligus salah satu titik awal Wangsa Sailendra yang kelak berkuasa di Mataram dan Sriwijaya.",
            citation: "Carita Parahiyangan (naskah tradisi Sunda) — sumber tradisi lokal, perlu verifikasi epigrafis lebih lanjut",
            url: "https://id.wikipedia.org/wiki/Kerajaan_Kalingga"
          },
        ]
      },
    ]
  },

